/* DrainPro-Bundle.css — page styles (extracted from inline \3c style>, 2026.09.05.11) */

/* Page theme (CSS standardization, 2026-09-07): this page's own colours, auto-named by hue so the page
   keeps its exact look. Map them to shared_components/css/tokens.css names when the page is redesigned;
   every rule below uses var(). Raw hex is allowed ONLY in this block. */
/* stylelint-disable color-no-hex */
:root {
    --rainro-undle-gray-dark: #32373c;
}
/* stylelint-enable color-no-hex */

/* ── moved from inline \3c style> in dashboards/DrainPro-Bundle.html (Rule 3, 2026.09.05.11) ── */
* {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
            background: var(--gray-100);
            color: var(--gray-800);
            line-height: 1.6;
        }

        /* Header - Fire Engine Red matching Drain-Pro brand */
        .drain-pro-header {
            background: linear-gradient(135deg, var(--red-500) 0%, var(--red-600) 100%);
            padding: 3rem 2rem;
            text-align: center;
            color: white;
            box-shadow: 0 4px 6px rgb(0 0 0 / 10%);
        }

        .logo-container {
            background: white;
            padding: 1.5rem 2rem;
            border-radius: 5px;
            display: inline-block;
            margin-bottom: 1.5rem;
            box-shadow: 0 2px 8px rgb(0 0 0 / 10%);
        }

        .logo-container img {
            height: 80px;
            display: block;
        }

        .header-title {
            font-size: 2rem;
            font-weight: 700;
            margin-bottom: 0.5rem;
            text-shadow: 0 2px 4px rgb(0 0 0 / 10%);
        }

        .header-subtitle {
            font-size: 1.1rem;
            opacity: 0.95;
            font-weight: 400;
        }

        /* Main Content Container */
        .container {
            max-width: 1400px;
            margin: 2rem auto;
            padding: 0 1.5rem;
        }

        /* Content Card */
        .content-card {
            background: white;
            border-radius: 5px;
            padding: 2.5rem;
            box-shadow: 0 1px 3px rgb(0 0 0 / 10%);
            border-left: 5px solid var(--red-500);
        }

        .section-header {
            display: flex;
            align-items: center;
            gap: 0.75rem;
            color: var(--rainro-undle-gray-dark);
            font-size: 1.5rem;
            font-weight: 700;
            margin-bottom: 1.5rem;
            padding-bottom: 0.75rem;
            border-bottom: 2px solid var(--red-500);
        }

        .section-header i {
            color: var(--red-500);
        }

        /* Caspio Table Container */
        .table-container {
            margin: 2rem 0;
            background: var(--gray-50);
            padding: 1.5rem;
            border-radius: 5px;
            border: 1px solid var(--gray-200);
        }

        /* Navigation Buttons */
        .nav-buttons {
            display: flex;
            gap: 1rem;
            justify-content: center;
            margin-top: 2.5rem;
            padding-top: 2rem;
            border-top: 1px solid var(--gray-200);
            flex-wrap: wrap;
        }

        .btn {
            padding: 0.875rem 1.75rem;
            border-radius: 5px;
            text-decoration: none;
            font-weight: 600;
            font-size: 1rem;
            display: inline-flex;
            align-items: center;
            gap: 0.5rem;
            transition: all 0.3s ease;
            border: none;
            cursor: pointer;
        }

        .btn-primary {
            background: var(--rainro-undle-gray-dark);
            color: white;
        }

        .btn-primary:hover {
            background: var(--gray-800);
            transform: translateY(-2px);
            box-shadow: 0 4px 8px rgb(0 0 0 / 20%);
        }

        .btn-secondary {
            background: var(--gray-100);
            color: var(--gray-700);
            border: 1px solid var(--gray-300);
        }

        .btn-secondary:hover {
            background: var(--gray-200);
            border-color: var(--gray-400);
        }

        /* Info Banner */
        .info-banner {
            background: linear-gradient(135deg, var(--amber-100) 0%, var(--amber-200) 100%);
            border-left: 4px solid var(--amber-500);
            padding: 1rem 1.5rem;
            border-radius: 5px;
            margin-bottom: 2rem;
            display: flex;
            align-items: flex-start;
            gap: 1rem;
        }

        .info-banner i {
            color: var(--amber-500);
            font-size: 1.5rem;
            margin-top: 0.2rem;
            flex-shrink: 0;
        }

        .info-banner-content strong {
            color: var(--amber-800);
            display: block;
            margin-bottom: 0.25rem;
        }

        .info-banner-content {
            color: var(--amber-900);
            font-size: 0.95rem;
        }

        /* Stats Cards */
        .stats-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 1rem;
            margin-bottom: 2rem;
        }

        .stat-card {
            background: var(--gray-50);
            padding: 1.25rem;
            border-radius: 5px;
            border: 1px solid var(--gray-200);
            text-align: center;
        }

        .stat-value {
            font-size: 2rem;
            font-weight: 700;
            color: var(--red-500);
            margin-bottom: 0.25rem;
        }

        .stat-label {
            font-size: 0.875rem;
            color: var(--gray-500);
            text-transform: uppercase;
            letter-spacing: 0.025em;
        }

        /* Responsive Design */
        @media (width <= 768px) {
            .drain-pro-header {
                padding: 2rem 1rem;
            }

            .header-title {
                font-size: 1.5rem;
            }

            .header-subtitle {
                font-size: 1rem;
            }

            .content-card {
                padding: 1.5rem;
            }

            .logo-container {
                padding: 1rem 1.5rem;
            }

            .logo-container img {
                height: 60px;
            }

            .section-header {
                font-size: 1.25rem;
            }

            .nav-buttons {
                flex-direction: column;
            }

            .btn {
                width: 100%;
                justify-content: center;
            }
        }

        /* Tab Navigation */
        .tab-navigation {
            display: flex;
            gap: 0;
            border-bottom: 2px solid var(--gray-200);
            margin-bottom: 2rem;
        }

        .tab-button {
            flex: 1;
            padding: 1rem 1.5rem;
            background: transparent;
            border: none;
            border-bottom: 3px solid transparent;
            color: var(--gray-500);
            font-size: 1rem;
            font-weight: 600;
            cursor: pointer;
            transition: all 0.3s ease;
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 0.5rem;
            position: relative;
            bottom: -2px;
        }

        .tab-button:hover {
            color: var(--red-500);
            background: var(--red-50);
        }

        .tab-button.active {
            color: var(--red-500);
            border-bottom-color: var(--red-500);
            background: var(--red-50);
        }

        .tab-button i {
            font-size: 1.1rem;
        }

        .tab-content {
            display: none;
            animation: fadeIn 0.3s ease-in;
        }

        .tab-content.active {
            display: block;
        }

        @keyframes fadeIn {
            from {
                opacity: 0;
                transform: translateY(10px);
            }

            to {
                opacity: 1;
                transform: translateY(0);
            }
        }

        /* Instructions Box */
        .instructions-box {
            background: var(--gray-50);
            border-left: 4px solid var(--red-500);
            border-radius: 5px;
            padding: 1.5rem;
            margin-bottom: 2rem;
        }

        .instructions-title {
            display: flex;
            align-items: center;
            gap: 0.5rem;
            color: var(--rainro-undle-gray-dark);
            font-size: 1.1rem;
            font-weight: 700;
            margin-bottom: 1rem;
        }

        .instructions-title i {
            color: var(--red-500);
        }

        .instructions-list {
            list-style: none;
            padding: 0;
            margin: 0;
        }

        .instructions-list li {
            display: flex;
            align-items: flex-start;
            gap: 0.75rem;
            padding: 0.75rem 0;
            color: var(--gray-700);
            font-size: 0.95rem;
            line-height: 1.6;
        }

        .instruction-number {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            min-width: 28px;
            height: 28px;
            background: var(--red-500);
            color: white;
            border-radius: 50%;
            font-weight: 700;
            font-size: 0.875rem;
            flex-shrink: 0;
        }

        .instruction-text {
            padding-top: 0.2rem;
        }

        /* Print Styles */
        @media print {
            .drain-pro-header {
                /* stylelint-disable-next-line declaration-no-important -- legacy: outranks a higher-specificity rule — re-examine when this page is redesigned */
                background: white !important;
                /* stylelint-disable-next-line declaration-no-important -- legacy: outranks a higher-specificity rule — re-examine when this page is redesigned */
                color: var(--gray-800) !important;
                /* stylelint-disable-next-line declaration-no-important -- legacy: outranks a higher-specificity rule — re-examine when this page is redesigned */
                padding: 1rem !important;
                border-bottom: 3px solid var(--red-500);
            }

            .logo-container {
                /* stylelint-disable-next-line declaration-no-important -- legacy: outranks a higher-specificity rule — re-examine when this page is redesigned */
                background: none !important;
                /* stylelint-disable-next-line declaration-no-important -- legacy: outranks a higher-specificity rule — re-examine when this page is redesigned */
                box-shadow: none !important;
            }

            .nav-buttons {
                display: none;
            }

            .info-banner {
                /* stylelint-disable-next-line declaration-no-important -- legacy: outranks a higher-specificity rule — re-examine when this page is redesigned */
                background: white !important;
                border: 1px solid var(--amber-500);
            }

            .tab-navigation {
                display: none;
            }

            .tab-content {
                /* stylelint-disable-next-line declaration-no-important -- legacy: outranks a higher-specificity rule — re-examine when this page is redesigned */
